import json,subprocess,html,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=R/'evidence-v17'
def read(n):return json.loads((E/n).read_text())
def write(n,x):(E/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
checks=read('browser-checks.json');cross=read('browser-crossings.json');capture=read('capture-run.json');cold=read('blender-cold.json');assert not checks['errors'] and not capture['errors'];assert len(checks['entries'])==2 and capture['frames']==56
probes=[]
for row in capture['videos']:
 p=E/row['file'];v=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(p)]));probes.append({'file':row['file'],'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'format':v['format'],'streams':v['streams']})
write('video-probes.json',{'requested_wall_seconds':6,'note':'Actual encoded duration and frame rate below; CPU renderer timing is not device performance validation.','entries':probes})
summary={'version':'0.17.0','scope':'Run forearm rotations and Run-only elbow skin/garment corrective on two native bodies; six other clips and base asset bytes retained','programmatic':'passed; pins, native/GLB preservation, morph export, rejected unsafe edits, structure','blender_offline':'cold-open and evaluated surfaces passed; no offline art render','browser_actual':'Chromium SwiftShader playback, controls, same-camera A/B, 120 Hz bounded crossings, and diagnostic switch restoration passed','physical_mobile':'not-tested; 390px browser viewport only','human_art':'not-tested','godot_and_maps':'not-tested this version','art_approved':False,'game_ready':False,'browser':checks['entries'],'blender':cold['entries'],'crossings':[{'key':r['key'],'variants':[{k:v for k,v in x.items() if k!='samples'} for x in r['variants']]} for r in cross['entries']],'frames':capture['frames'],'videos':[{'file':p['file'],'encoded_duration_s':p['format'].get('duration')} for p in probes],'failed_trials':json.loads((R/'docs/TRIALS_V17.json').read_text())['trials'],'known_defects':['Inherited source arm/armpit skin self crossings remain: maximum 9 Vivi and 3 Vita in bounded Run checks; not a zero-collision body.','Visual inspection: Vivi shoulder/armpit dark triangular fold remains visible and is more exposed in some new poses; sleeve cuffs remain angular. No art pass claimed.','Procedural gait naturalness and complete clothing silhouette await human art review.'],'limitations':['Vivi flexion 68–92 degrees; Vita 68–80. Native hinge/phase rules shared, body-specific amplitude and local fitting required.','Run-only correction; no new Walk/Run transitions or arbitrary-speed controller.','Proper edge crossings only: no solid containment, coplanar overlap, garment thickness or full-body certification.','Original base geometry/UV/weights/textures preserved, but Run morph intentionally moves local skin and sleeve vertices.','Upstream .vroid project unavailable; original VRM and editable Blender derivatives included.']};write('acceptance-summary.json',summary)
frames=read('frame-catalog.json');parts=['<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>V17 雙身形跑步手肘與衣袖證據</title><style>body{font:16px system-ui;max-width:1250px;margin:30px auto;padding:15px;background:#f4f6f2;color:#163e35}img{width:48%;margin:.5%}video{width:48%}a{color:#126a58}h2{margin-top:36px}</style><h1>V17 跑步手肘與衣袖前後比較</h1><p>A：Vivi 0.4／Vita 0.3；B：Vivi 0.5／Vita 0.4。停用局部修正的畫面是失敗試作，僅供診斷。實際瀏覽器、同鏡位、同時間；全部待人工美術驗收。</p><p><a href="../web-v17/">開啟互動驗收場</a> · <a href="acceptance-summary.json">完整狀態</a> · <a href="video-probes.json">錄影實際長度</a></p>']
for v in capture['videos']:parts.append('<video controls loop muted src="'+v['file']+'"></video>')
for sequence in frames['sequences']:
 parts.append('<h2>'+html.escape(sequence['key']+' · '+sequence['view'])+'</h2>')
 for frame in sequence['frames']:parts.append(('<p>'+('修正啟用' if frame['corrective_enabled'] else '修正停用：失敗試作，僅供診斷')+'</p>' if 'corrective_enabled' in frame else '')+'<a href="'+frame['file']+'"><img loading="lazy" src="'+frame['file']+'" alt="'+str(frame['time_s'])+' 秒"></a>')
(E/'index.html').write_text(''.join(parts)+'</html>');print('V17_EVIDENCE_READY')
